40	@Entity
41	@Table(name = "owners")
42	public class Owner extends Person {
43	    @Column(name = "title")
44	    private String title;
45	
46	    @Column(name = "address")
47	    @NotEmpty
48	    private String address;
49	
50	    @Column(name = "address_line1")
51	    private String addressLine1;
52	
53	    @Column(name = "address_line2")
54	    private String addressLine2;
55	
56	    @Column(name = "city")
57	    @NotEmpty
58	    private String city;
59	
60	    @Column(name = "telephone")
61	    @NotEmpty
62	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
63	    private String telephone;
64	
65	    @Column(name = "email")
66	    private String email;
67	
68	    @Column(name = "postcode")
69	    private String postcode;
70	
71	    @Column(name = "registration_date")
72	    private LocalDate registrationDate;
73	
74	    @Column(name = "birth_date")
75	    private LocalDate birthDate;
76	
77	    @Column(name = "customer_code")
78	    private String customerCode;
79	
80	    @Column(name = "household_id")
81	    private String householdId;
82	
83	    @Column(name = "namesake_count")
84	    private Integer namesakeCount;
85	
86	    @Column(name = "household_size")
87	    private Integer householdSize;
88	
89	    @Column(name = "membership_number")
90	    private String membershipNumber;
91	
92	    @Column(name = "membership_level_cap")
93	    private Integer membershipLevelCap;
94	
95	    @Column(name = "possible_duplicate_of")
96	    private Integer possibleDuplicateOf;
97	
98	    @Column(name = "deleted", nullable = false)
99	    private boolean deleted;
100	
101	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
102	    private Set<Pet> pets;
103	
104	    /**
105	     * Default the registration date to the server's current date when none was
106	     * supplied, then roll the effective date forward onto a business day so a
107	     * weekend registration date always lands on the following Monday. Runs only
108	     * on insert.
109	     */
110	    @PrePersist
111	    private void defaultRegistrationDate() {
112	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
113	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
114	    }
115	
116	    public String getTitle() {
117	        return this.title;
118	    }
119	
120	    public void setTitle(String title) {
121	        this.title = title;
122	    }
123	
124	    public String getAddress() {
125	        return this.address;
126	    }
127	
128	    public void setAddress(String address) {
129	        this.address = address;
130	    }
131	
132	    public String getAddressLine1() {
133	        return this.addressLine1;
134	    }
135	
136	    public void setAddressLine1(String addressLine1) {
137	        this.addressLine1 = addressLine1;
138	    }
139	
140	    public String getAddressLine2() {
141	        return this.addressLine2;
142	    }
143	
144	    public void setAddressLine2(String addressLine2) {
145	        this.addressLine2 = addressLine2;
146	    }
147	
148	    public String getCity() {
149	        return this.city;
150	    }
151	
152	    public void setCity(String city) {
153	        this.city = city;
154	    }
155	
156	    public String getTelephone() {
157	        return this.telephone;
158	    }
159	
160	    public void setTelephone(String telephone) {
161	        this.telephone = telephone;
162	    }
163	
164	    public String getEmail() {
165	        return this.email;
166	    }
167	
168	    public void setEmail(String email) {
169	        this.email = email;
170	    }
171	
172	    public String getPostcode() {
173	        return this.postcode;
174	    }
175	
176	    public void setPostcode(String postcode) {
177	        this.postcode = postcode;
178	    }
179	
180	    public LocalDate getRegistrationDate() {
181	        return this.registrationDate;
182	    }
183	
184	    public void setRegistrationDate(LocalDate registrationDate) {
185	        this.registrationDate = registrationDate;
186	    }
187	
188	    public LocalDate getBirthDate() {
189	        return this.birthDate;
190	    }
191	
192	    public void setBirthDate(LocalDate birthDate) {
193	        this.birthDate = birthDate;
194	    }
195	
196	    public String getCustomerCode() {
197	        return this.customerCode;
198	    }
199	
200	    public void setCustomerCode(String customerCode) {
201	        this.customerCode = customerCode;
202	    }
203	
204	    public String getHouseholdId() {
205	        return this.householdId;
206	    }
207	
208	    public void setHouseholdId(String householdId) {
