212	    public Integer getNamesakeCount() {
213	        return this.namesakeCount;
214	    }
215	
216	    public void setNamesakeCount(Integer namesakeCount) {
217	        this.namesakeCount = namesakeCount;
218	    }
219	
220	    public Integer getHouseholdSize() {
221	        return this.householdSize;
222	    }
223	
224	    public void setHouseholdSize(Integer householdSize) {
225	        this.householdSize = householdSize;
226	    }
227	
228	    public String getMembershipNumber() {
229	        return this.membershipNumber;
230	    }
231	
232	    public void setMembershipNumber(String membershipNumber) {
233	        this.membershipNumber = membershipNumber;
234	    }
235	
236	    public Integer getMembershipLevelCap() {
237	        return this.membershipLevelCap;
238	    }
239	
240	    public void setMembershipLevelCap(Integer membershipLevelCap) {
241	        this.membershipLevelCap = membershipLevelCap;
242	    }
243	
244	    public Integer getPossibleDuplicateOf() {
245	        return this.possibleDuplicateOf;
246	    }
247	
248	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
249	        this.possibleDuplicateOf = possibleDuplicateOf;
250	    }
251	
252	    /**
253	     * Return whether this owner has been soft-deleted. A newly created owner is not deleted; a
254	     * {@code DELETE /api/owners/{id}} flags the owner deleted while retaining its record.
255	     */
256	    public boolean isDeleted() {
257	        return this.deleted;
258	    }
259	
260	    public void setDeleted(boolean deleted) {
261	        this.deleted = deleted;
262	    }
263	
264	    /**
265	     * Return this owner's self link: the canonical API path of this owner, {@code /api/owners/}
266	     * followed by its {@link #getId() id}.
267	     */
268	    @Transient
269	    public String getSelfLink() {
270	        return "/api/owners/" + this.getId();
271	    }
272	
273	    /**
274	     * Return whether this owner is a possible duplicate: true when it was created while an existing
275	     * owner's last name shared its Soundex code at the same postcode (yet resolved to a different
276	     * identity key), i.e. when a {@link #getPossibleDuplicateOf() possible-duplicate-of} owner id is
277	     * present.
278	     */
279	    @Transient
280	    public boolean getPossibleDuplicate() {
281	        return this.possibleDuplicateOf != null;
282	    }
283	
284	    /**
285	     * Return this owner's name formatted as {@code LastName, FirstName}.
286	     */
287	    @Transient
288	    public String getDisplayName() {
289	        return this.getLastName() + ", " + this.getFirstName();
290	    }
291	
292	    /**
293	     * Return this owner's salutation: the {@link #getTitle() title} followed by a space and the
294	     * last name (e.g. {@code DR Franklin}), or just the last name when no title was supplied.
295	     */
296	    @Transient
297	    public String getSalutation() {
298	        if (this.title == null || this.title.isBlank()) {
299	            return this.getLastName();
300	        }
301	        return this.title + " " + this.getLastName();
302	    }
303	
304	    /**
305	     * Return this owner's telephone formatted for human display: the country code, a space, then
306	     * the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The raw
307	     * {@link #getTelephone() telephone} remains in canonical E.164 form.
308	     */
309	    @Transient
310	    public String getTelephoneDisplay() {
311	        return TelephoneFormatter.format(this.telephone);
312	    }
313	
314	    /**
315	     * Return this owner's identity key: the lower-case SHA-256 hex digest of
316	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (an absent email
317	     * contributes an empty segment). Two owners are the same person — a hard duplicate — exactly
318	     * when their identity keys match; owners who merely share a household (same last name and
319	     * postcode) but differ in telephone, email or surname sound derive distinct keys. The telephone
320	     * and email are expected to already be in their normalized storage form.
321	     */
322	    @Transient
323	    public String getIdentityKey() {
324	        String raw = orEmpty(this.telephone) + "|" + orEmpty(this.email).toLowerCase(Locale.ROOT)
325	            + "|" + Soundex.encode(this.getLastName());
326	        return Sha256.hex(raw);
327	    }
328	
329	    private static String orEmpty(String value) {
330	        return value == null ? "" : value;
331	    }
332	
333	    /**
334	     * Return this owner's locality: the REGION segment of the owner's
335	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
336	     * When no customer code has been assigned yet the region is resolved directly from the
337	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
338	     */
339	    @Transient
340	    public String getLocality() {
341	        if (this.customerCode != null && !this.customerCode.isBlank()) {
342	            return CustomerCodeGenerator.regionOf(this.customerCode);
343	        }
344	        return RegionResolver.regionFor(this.postcode, this.city);
345	    }
346	
347	    /**
348	     * Return this owner's timezone: the IANA name mapped from the owner's
349	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table. Null when the
350	     * region has no known timezone.
351	     */
352	    @Transient
353	    public String getTimezone() {
354	        return RegionTimezones.timezoneOf(getLocality());
355	    }
356	
357	    /**
358	     * Return this owner's membership points: starting at 0, plus 2 when the owner has an email,
359	     * plus 1 when the owner is uniquely named (a {@link #getNamesakeCount() namesakeCount} of 0),
360	     * plus 2 for a household of three or more ({@link #getHouseholdSize() household size}), plus 3
361	     * for long tenure ({@link #getTenureFiscalYears() tenure} of more than one fiscal year).
362	     */
363	    @Transient
364	    public int getMembershipPoints() {
365	        boolean hasEmail = this.email != null && !this.email.isEmpty();
366	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
367	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
368	        boolean longTenure = getTenureFiscalYears() > 1;
369	        return MembershipPoints.of(hasEmail, uniquelyNamed, largeHousehold, longTenure);
370	    }
371	
372	    /**
373	     * Return this owner's membership level: the band their {@link #getMembershipPoints() membership
374	     * points} fall into — 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more — capped so it
375	     * never exceeds one above the highest level among the household members present when this owner
376	     * was created (see {@link #getMembershipLevelCap() membership level cap}). No cap applies to an
377	     * owner created without any existing household member.
378	     */
379	    @Transient
380	    public int getMembershipLevel() {
381	        int level = MembershipPoints.levelFor(getMembershipPoints());
382	        return this.membershipLevelCap == null ? level : Math.min(level, this.membershipLevelCap);
383	    }
384	
385	    /**
386	     * Return this owner's fiscal year: the fiscal year of the business-day-adjusted
387	     * {@link #getRegistrationDate() registration date}, formatted {@code FY<YY>}. The fiscal year
388	     * starts on 1 July. Null when no registration date is known.
389	     */
390	    @Transient
391	    public String getFiscalYear() {
392	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
393	    }
394	
395	    /**
396	     * Return this owner's tenure in whole fiscal years: the number of fiscal years elapsed from the
397	     * {@link #getRegistrationDate() registration date} to today, i.e. the count of 1 July
398	     * fiscal-year boundaries crossed. A newly created owner registered in the current fiscal year
399	     * has zero tenure. Zero when no registration date is known.
400	     */
401	    @Transient
402	    public int getTenureFiscalYears() {
403	        if (this.registrationDate == null) {
404	            return 0;
405	        }
406	        return FiscalYear.elapsedBetween(this.registrationDate, LocalDate.now());
407	    }
408	
409	    /**
410	     * Return this owner's check digit: the single Luhn check digit computed over the
411	     * digits of the {@link #getCustomerCode() customer code}.
412	     */
413	    @Transient
414	    public int getCheckDigit() {
415	        return LuhnCheckDigit.of(this.customerCode);
416	    }
417	
418	    /**
419	     * Return this owner's preferred contact channel: {@code EMAIL} when an
420	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
421	     */
422	    @Transient
423	    public String getContactPreference() {
424	        boolean hasEmail = this.email != null && !this.email.isEmpty();
425	        return hasEmail ? "EMAIL" : "PHONE";
426	    }
427	
428	    /**
429	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
430	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
431	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
432	     */
433	    @Transient
434	    public String getAgeBand() {
435	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
436	        return ageBand == null ? null : ageBand.name();
437	    }
438	
439	    protected Set<Pet> getPetsInternal() {
440	        if (this.pets == null) {
441	            this.pets = new HashSet<>();
442	        }
443	        return this.pets;
444	    }
445	
446	    protected void setPetsInternal(Set<Pet> pets) {
447	        this.pets = pets;
448	    }
449	
450	    public List<Pet> getPets() {
451	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
452	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
453	        return Collections.unmodifiableList(sortedPets);
454	    }
455	
456	    public void setPets(List<Pet> pets) {
457	        this.pets = new HashSet<>(pets);
458	    }
459	
460	    public void addPet(Pet pet) {
461	        getPetsInternal().add(pet);
462	        pet.setOwner(this);
463	    }
464	
465	    /**
466	     * Return the Pet with the given name, or null if none found for this Owner.
467	     *
468	     * @param name to test
469	     * @return true if pet name is already in use
470	     */
471	    public Pet getPet(String name) {
472	        return getPet(name, false);
473	    }
474	
475	    /**
476	     * Return the Pet with the given name, or null if none found for this Owner.
477	     *
478	     * @param name to test
479	     * @return true if pet name is already in use
480	     */
481	    public Pet getPet(String name, boolean ignoreNew) {
482	        name = name.toLowerCase();
483	        for (Pet pet : getPetsInternal()) {
484	            if (!ignoreNew || !pet.isNew()) {
485	                String compName = pet.getName();
486	                compName = compName.toLowerCase();
487	                if (compName.equals(name)) {
488	                    return pet;
489	                }
490	            }
491	        }
492	        return null;
493	    }
494	
495	    public Pet getPet(Integer petId) {
496	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
497	    }
498	
499	    @Override
500	    public String toString() {
501	        return new ToStringCreator(this)
502	
503	            .append("id", this.getId())
504	            .append("new", this.isNew())
505	            .append("lastName", this.getLastName())
506	            .append("firstName", this.getFirstName())
507	            .append("address", this.address)
508	            .append("city", this.city)
509	            .append("telephone", this.telephone)
510	            .append("email", this.email)
511	            .toString();
512	    }
513	}
